files.big-numbers.css:
.dash { background: #000; color: #f2f0ea; font-family: "Saira VF", Saira, sans-serif; user-select: none; }
.grid { display: grid; grid-template: 1fr 1fr / 1fr 1fr; gap: 2px; height: 100%; background: #222; }
.cell { container-type: size; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #000; }
.num { font-size: min(34cqh, 26cqw); font-weight: 700; font-stretch: 85%; line-height: 1; font-variant-numeric: tabular-nums; }
.lbl { margin-top: 4cqh; font-size: min(9cqh, 7cqw); font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: #9a978f; }
.dim .num { color: #6b6963; }
.bn-set { position: absolute; inset: 0; z-index: 2; display: flex; flex-direction: column; justify-content: center; gap: 14px; padding: 24px; background: #000d; font-size: 18px; }
.bn-set label { display: flex; align-items: center; justify-content: space-between; gap: 12px; color: #9a978f; }
.bn-set select, .bn-set button { font: inherit; color: #f2f0ea; background: #1b1b1b; border: 1px solid #444; border-radius: 8px; padding: 10px 12px; }
.bn-set button { margin-top: 10px; font-weight: 700; }

files.index.js:
// Big numbers: four readings the person picks, each filling a quarter of the screen, in their
// display units. Uses only the raw dash API (no kit), so the whole dash is this file, units.js and
// big-numbers.css. Readings arrive in base units (kPa, °C, km/h, lambda); units.js turns them into
// the person's.
// Its settings are its own: which four readings, kept in its store and picked in its panel, which
// the app's gear opens (api.on('settings')).
import { LABELS, show } from './units.js';

const DEFAULT = ['rpm', 'oil_temp_c', 'oil_kpa', 'lambda1'];

export default function mount(api) {
  // What the store holds is checked: a key this dash doesn't know gives way to the default.
  const kept = api.store.get('keys');
  let keys = DEFAULT.map((k, i) => (Array.isArray(kept) && Object.hasOwn(LABELS, kept[i]) ? kept[i] : k));
  api.root.innerHTML = `<div class="grid">${keys.map(() => '<div class="cell"><div class="num">-</div><div class="lbl"></div></div>').join('')}</div>`;
  const cells = [...api.root.querySelectorAll('.cell')];
  let units = api.units, last = {}, dim = false, dirty = true;

  const label = (k) => {
    const unit = show(k, null, units).unit;
    return `${LABELS[k] || k}${unit ? ` · ${unit}` : ''}`;
  };
  const relabel = () => { keys.forEach((k, i) => { cells[i].querySelector('.lbl').textContent = label(k); }); dirty = true; };
  relabel();

  api.on('reading', (v, t, m) => { last = v || {}; dim = !!m.dim; dirty = true; });
  api.on('units', (u) => { units = u; relabel(); });
  api.on('settings', openPanel);

  function openPanel() {
    api.root.querySelector('.bn-set')?.remove();
    api.nav.hide();
    const el = document.createElement('div');   // not a form: the frame's sandbox blocks submitting one
    el.className = 'bn-set';
    const options = (now) => Object.keys(LABELS).map((k) => `<option value="${k}"${k === now ? ' selected' : ''}>${LABELS[k]}</option>`).join('');
    el.innerHTML = keys.map((k, i) => `<label>${['Top left', 'Top right', 'Bottom left', 'Bottom right'][i]}<select>${options(k)}</select></label>`).join('')
      + '<button type="button">Done</button>';
    el.querySelector('button').addEventListener('click', () => {
      keys = [...el.querySelectorAll('select')].map((s) => s.value);
      api.store.set('keys', keys);
      relabel();
      el.remove();
    });
    api.root.append(el);
  }

  // Numbers change at most 4 times a second, so they can be read, drawn on the screen's own clock.
  let shownAt = 0;
  (function frame(now) {
    if (dirty && now - shownAt > 250) {
      keys.forEach((k, i) => { cells[i].querySelector('.num').textContent = show(k, last[k], units).text; });
      api.root.classList.toggle('dim', dim);
      dirty = false; shownAt = now;
    }
    requestAnimationFrame(frame);
  })(0);

  // The tab bar: a tap anywhere but the panel hides it or brings it back.
  api.root.addEventListener('click', (e) => { if (!e.target.closest('.bn-set')) api.nav.shown ? api.nav.hide() : api.nav.show(); });
}

files.units.js:
// The readings this dash knows, their labels, and how each shows in the person's units.
export const LABELS = {
  rpm: 'RPM', map_kpa: 'MAP', tps_pct: 'Throttle', ect_c: 'Head temp', iat_c: 'Intake temp', oil_temp_c: 'Oil temp',
  oil_kpa: 'Oil press', fuel_kpa: 'Fuel press', lambda1: 'Lambda 1', lambda2: 'Lambda 2', lambda_target: 'Lambda target',
  battery_v: 'Battery', ign_deg: 'Ignition', speed_kmh: 'Speed', g_lat: 'G lateral', g_long: 'G long',
};
const KIND = { map_kpa: 'pressure', oil_kpa: 'pressure', fuel_kpa: 'pressure', ect_c: 'temperature', iat_c: 'temperature', oil_temp_c: 'temperature',
  speed_kmh: 'speed', lambda1: 'mixture', lambda2: 'mixture', lambda_target: 'mixture' };
const PLAIN = { rpm: ['', 0], tps_pct: ['%', 0], battery_v: ['V', 1], ign_deg: ['°', 1], g_lat: ['g', 2], g_long: ['g', 2] };
const CONVERT = {
  pressure: { kpa: ['kPa', 0, (x) => x], bar: ['bar', 2, (x) => x / 100], psi: ['psi', 0, (x) => x * 0.1450377] },
  temperature: { c: ['°C', 0, (x) => x], f: ['°F', 0, (x) => x * 9 / 5 + 32] },
  speed: { kmh: ['km/h', 0, (x) => x], mph: ['mph', 0, (x) => x * 0.6213712] },
  mixture: { lambda: ['λ', 2, (x) => x], afr: ['AFR', 1, (x) => x * 14.7] },
};

// {text, unit} for a reading in base units (null: none), in the person's units.
export function show(key, v, units) {
  const kind = KIND[key];
  const [unit, dp, f] = kind ? (CONVERT[kind][units?.[kind]] || Object.values(CONVERT[kind])[0]) : [...(PLAIN[key] || ['', 1]), (x) => x];
  return { unit, text: typeof v === 'number' && Number.isFinite(v) ? f(v).toFixed(dp) : '-' };
}
